/**
 * @file        virtual-audio-files.d.ts
 * @author      Sherman Goh Wee Hao
 * @date        2026-10-04
 * @brief       Type declaration for the virtual:audio-files Vite module.
 *
 * @responsibility
 * Tells TypeScript the shape of the virtual module generated by the audio
 * auto-discovery plugin in vite.config.ts, which lists the bundled audio
 * filenames found at build time.
 *
 * @boundary
 * Declaration only. No runtime code; the plugin provides the value.
 *
 * @dependencies
 * None. Pairs with the audio-discovery plugin in vite.config.ts.
 *
 * @status
 * Current implementation, used by the M1 build.
 *
 * @documentation
 * Larger system guide: https://github.com/gsherman01/Project5_Team17_DoReMi-yaki/wiki/Audio-System
 * Links point at the project wiki; migration is still in progress.
 */
declare module 'virtual:audio-files' {
  const audioFileNames: string[]
  export default audioFileNames
}
